INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(48911, 'Jeremiah 29:9', 'Jeremiah', 29, 9, 'ځکه هغوئ تاسو ته زما په نوم د دروغو پېشګوئې کوى. هغوئ ما تاسو ته نۀ دى درلېږلى. مالِک خُدائ داسې فرمائى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah29_verse_9.mp3', '', 1761754199, 1761754199),
(48912, 'Jeremiah 29:10', 'Jeremiah', 29, 10, 'مالِک خُدائ فرمائى چې، کله چې په بابل کښې ستاسو اويا کاله تېر شى، نو زۀ به ستاسو خوا ته راشم او خپله هغه د رحم وعده به پوره کړم چې تاسو بيا واپس خپل مُلک ته راولم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah29_verse_10.mp3', '', 1761754199, 1761754199),
(48913, 'Jeremiah 29:11', 'Jeremiah', 29, 11, 'مالِک خُدائ فرمائى چې، ما ته د هغه منصوبو پته ده زۀ چې کومې ستاسو دپاره لرم، هغه منصوبه چې تاسو آبادوى او خوشحالوى، نه چې تاسو ته نقصان رسوى، هغه منصوبه چې تاسو ته مستقبل او اُميد درکړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah29_verse_11.mp3', '', 1761754199, 1761754199),
(48914, 'Jeremiah 29:12', 'Jeremiah', 29, 12, 'بيا به په هغه وخت تاسو ما ته مِنت زارى وکړئ، ما ته به رجوع وکړئ او ما نه به دُعا وغواړئ، او زۀ به ستاسو دُعا واورم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah29_verse_12.mp3', '', 1761754199, 1761754199),
(48915, 'Jeremiah 29:13', 'Jeremiah', 29, 13, 'تاسو به زما لټون کوئ او کۀ چرې په پوره زړۀ سره زما لټون وکړئ نو تاسو به مې پېدا کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah29_verse_13.mp3', '', 1761754199, 1761754199),
(48916, 'Jeremiah 29:14', 'Jeremiah', 29, 14, 'مالِک خُدائ فرمائى چې، زۀ به تاسو ته اجازت درکړم چې ما پېدا کړئ. زۀ به ستاسو مُلک دوباره تاسو له درکړم. د هغه ټولو مُلکونو او ځايونو نه به تاسو واپس راولم په کومو کښې چې ما خوارۀ کړى وئ، او زۀ به تاسو هغه مُلک ته واپس راولم د کوم نه چې ما تاسو جلاوطن کړى وئ، مالِک خُدائ فرمائى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah29_verse_14.mp3', '', 1761754199, 1761754199),
(48917, 'Jeremiah 29:15', 'Jeremiah', 29, 15, 'تاسو ووايئ چې، مونږ دپاره مالِک خُدائ په بابل کښې هم پېغمبران راپېدا کړى دى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah29_verse_15.mp3', '', 1761754199, 1761754199),
(48918, 'Jeremiah 29:16', 'Jeremiah', 29, 16, 'خو مالِک خُدائ ته غوږ ونيسئ چې هغه د هغه بادشاه په حقله فرمائى څوک چې د داؤد په تخت ناست دے او د هغه خلقو په حقله څوک چې په دې ښار کښې پاتې شوى دى، او ستاسو د مُلک خلقو په حقله څوک چې تاسو سره جلاوطن شوى نۀ وُو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah29_verse_16.mp3', '', 1761754199, 1761754199),
(48919, 'Jeremiah 29:17', 'Jeremiah', 29, 17, 'مالِک خُدائ ربُ الافواج فرمائى چې، زۀ به په هغوئ باندې جنګ، قحط او وبا راولم او هغوئ به د هغه خرابو اينځرو په شان کړم چې د خوړلو قابل نۀ وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah29_verse_17.mp3', '', 1761754199, 1761754199),
(48920, 'Jeremiah 29:18', 'Jeremiah', 29, 18, 'زۀ به په هغوئ جنګ، قحط او وبا نازله کړم او د هغوئ پسې به يم، او د دُنيا ټول نور قومونه چې هغوئ ته ګورى نو ورته به د يرې او دهشت مثال وى او چې چرته هم هغوئ خوارۀ کړم نو ټولو خلقو ته به يې د نفرت او سپکاوى باعث وګرځوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah29_verse_18.mp3', '', 1761754199, 1761754199),
(48921, 'Jeremiah 29:19', 'Jeremiah', 29, 19, 'مالِک خُدائ فرمائى چې، ځکه چې هغوئ زما کلام ته غوږ نۀ نيولو، هغه پېغام چې ما بار بار د خپلو خادِمانو نبيانو په ذريعه هغوئ ته ورکړے وو. او تاسو جلاوطنو هم زما پېغام ته غوږ ونۀ نيولو، مالِک خُدائ فرمائى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah29_verse_19.mp3', '', 1761754199, 1761754199),
(48922, 'Jeremiah 29:20', 'Jeremiah', 29, 20, 'نو اوس تاسو ټولو اے جلاوطن شوو څوک چې ما د يروشلم نه بابل ته لېږلئ د مالِک خُدائ کلام واورئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah29_verse_20.mp3', '', 1761754199, 1761754199),
(48923, 'Jeremiah 29:21', 'Jeremiah', 29, 21, 'مالِک خُدائ ربُ الافواج، د بنى اِسرائيلو خُدائ پاک د اخى‌اب د قولاياه د زوئ او د صدقياه د معسياه د زوئ په حقله فرمائى چې، هغوئ تاسو ته زما په نوم د دروغو پېشګويانې وکړى، زۀ به هغوئ نبوکدنضر د بابل بادشاه ته حواله کړم، او هغه به هغوئ ستا د سترګو د وړاندې مړۀ کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah29_verse_21.mp3', '', 1761754199, 1761754199),
(48924, 'Jeremiah 29:22', 'Jeremiah', 29, 22, 'ځکه چې د هغوئ په وجه به، د يهوداه نه ټول جلاوطن شوى خلق څوک چې په بابل کښې قېديان دى هغوئ به داسې ښېرې کوى، مالِک خُدائ دې تاسو سره د صدقياه او اخى‌اب په شان کار وکړى څوک چې د بابل بادشاه په اور کښې سوزولى وُو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah29_verse_22.mp3', '', 1761754199, 1761754199),
(48925, 'Jeremiah 29:23', 'Jeremiah', 29, 23, 'ځکه چې هغوئ په بنى اِسرائيلو کښې شرمناک ګناهونه کړى دى، هغوئ د خپلو ګاونډيانو د ښځو سره د زنا باوجود، زما په نامه د دروغو پېغام خلقو ته وړاندې کړے دے د کوم چې ما هغوئ ته حُکم نۀ دے ورکړے. خو ما ته د هغوئ په حقله عِلم دے او په هغوئ باندې زۀ ګواه يم. مالِک خُدائ داسې فرمائى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah29_verse_23.mp3', '', 1761754199, 1761754199),
(48926, 'Jeremiah 29:24', 'Jeremiah', 29, 24, 'مالِک خُدائ په بابل کښې دا پېغام سمعياه نحلامى ته راولېږلو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah29_verse_24.mp3', '', 1761754199, 1761754199),
(48927, 'Jeremiah 29:25', 'Jeremiah', 29, 25, '”مالِک خُدائ ربُ الافواج د بنى اِسرائيلو خُدائ پاک داسې فرمائى چې، تا په خپل اختيار سره يو خط صفنياه د معسياه زوئ، اِمام ته، او تا د دې نقل نورو اِمامانو او د يروشلم خلقو ته ولېږلو، چې په کښې تا وليکلو چې،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah29_verse_25.mp3', '', 1761754199, 1761754199),
(48928, 'Jeremiah 29:26', 'Jeremiah', 29, 26, 'تۀ مالِک خُدائ د يهويدع په ځائ اِمام جوړ کړې او هغۀ تۀ د خپل کور مشر جوړ کړې. نو تا ته په کار دى چې هر يو ليونے کس چې په دروغو سره نبوت کوى د لرګى په کنده کښې بند کړې او په غاړه کښې ورته د اوسپنې زنځير واچوې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah29_verse_26.mp3', '', 1761754199, 1761754199),
(48929, 'Jeremiah 29:27', 'Jeremiah', 29, 27, 'نو بيا تاسو د عنتوت يرمياه ته زورنه ولې نۀ ده ورکړې، چا چې ستاسو په مينځ کښې د پېغمبرۍ دعوىٰ کوله او خلقو ته يې د پېغمبرۍ خبرې کولې؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah29_verse_27.mp3', '', 1761754199, 1761754199),
(48930, 'Jeremiah 29:28', 'Jeremiah', 29, 28, 'ځکه چې مونږ ته په بابل کښې هغۀ پېغام راولېږلو، او پېشګوئې يې وکړه چې زمونږ په جلاوطنۍ کښې به ډېر وخت لګيږى. نو هغۀ ووئيل، تاسو په دې وجه کورونه جوړ کړئ او هلته په کښې اوسېږئ، باغونه وکَرئ او د هغې مېوې خورئ.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah29_verse_28.mp3', '', 1761754199, 1761754199),
(48931, 'Jeremiah 29:29', 'Jeremiah', 29, 29, 'صفنياه اِمام دا خط يرمياه نبى ته ولوستلو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah29_verse_29.mp3', '', 1761754199, 1761754199),
(48932, 'Jeremiah 29:30', 'Jeremiah', 29, 30, 'او بيا د مالِک خُدائ کلام په يرمياه نازل شو چې،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah29_verse_30.mp3', '', 1761754199, 1761754199),
(48933, 'Jeremiah 29:31', 'Jeremiah', 29, 31, '”ټولو جلاوطنو ته خط ورولېږه او ورته وليکه چې، مالِک خُدائ د سمعياه نحلامى په حقله فرمائى چې، هغۀ د خپل ځان نه تاسو ته پېشګوئې کړې ده، او کۀ څۀ هم چې هغه ما تاسو ته نۀ دے درلېږلے. او هغۀ تاسو داسې تيار کړئ چې د هغۀ په دروغو باندې باور وکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah29_verse_31.mp3', '', 1761754199, 1761754199),
(48934, 'Jeremiah 29:32', 'Jeremiah', 29, 32, 'نو بيا په دې وجه مالِک خُدائ داسې فرمائى چې، زۀ به سمعياه نحلامى او د دۀ اولاد ته په يقين سره سزا ورکړم. د هغۀ د خاندان نه به څوک هم ژوندى پاتې نۀ شى، او نۀ به هغوئ هغه احسانونه او نعمتونه وګورى کوم چې زۀ د خپل غوره شوى قوم سره کوم، ځکه چې هغۀ زما خلاف خلقو ته د سرکشۍ کولو لمسون وکړو، مالِک خُدائ فرمائى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah29_verse_32.mp3', '', 1761754199, 1761754199),
(48935, 'Nahum 1:1', 'Nahum', 1, 1, 'څښتن دا پیغام چې د نینوا په هکله دی، په رویا کې ناحوم ته چې د القوش د کلي څخه ؤ، ورکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nahum1_verse_1.mp3', '', 1761754199, 1761754199),
(48936, 'Nahum 1:2', 'Nahum', 1, 2, 'غیرتي دی څښتن او دی بدل اخیستونکی خدای څښتن اخلي بدل او دی غضبناک څښتن بدل اخلي د خپلو رقیبانو څخه او تل وي په قهر خپلو دښمنانو ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nahum1_verse_2.mp3', '', 1761754199, 1761754199),
(48937, 'Nahum 1:3', 'Nahum', 1, 3, 'نه په قهریږي څښتن زر خو قدرتمند دی هغه هېڅکله نه پرېږدي بې له سزا ګناهکار چېرته چې ګرځي څښتن نو شي راپورته تېز باد او توفانونه دي ورېځې د هغه د پښو خاورې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nahum1_verse_3.mp3', '', 1761754199, 1761754199),
(48938, 'Nahum 1:4', 'Nahum', 1, 4, 'کوي حکم بحیرې ته او وچوي هغه وچوي هغه ټول سیندونه وچوي ځمکې د باشان د سیمې او ونې د کرمل د غره او مړاوي کوي هغه ګلان د لبنان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nahum1_verse_4.mp3', '', 1761754199, 1761754199),
(48939, 'Nahum 1:5', 'Nahum', 1, 5, 'غرونه لړزیږي د څښتن حضور کې غونډۍ شي ورانې او هوارې د هغه په مخکې ځمکه شي په لړزان په رېږدېدو شي جهان او په کې ټول خلک', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nahum1_verse_5.mp3', '', 1761754199, 1761754199),
(48940, 'Nahum 1:6', 'Nahum', 1, 6, 'څوک ودرېدلی شي د هغه د قهر په وړاندې؟ څوک شي زغملی سخت قهر د هغه؟ نازلیږي د هغه غضب لکه د اور په شان د هغه په مخکې ټوټې ټوټې شي ګټان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nahum1_verse_6.mp3', '', 1761754199, 1761754199),
(48941, 'Nahum 1:7', 'Nahum', 1, 7, 'نېک دی څښتن د تکلیف په وخت کې قوي کلا ده هغه کوي پام په هغو خلکو باندې چې راوړي پناه هغه ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nahum1_verse_7.mp3', '', 1761754199, 1761754199),
(48942, 'Nahum 1:8', 'Nahum', 1, 8, 'خو تباه کوي خپل رقیبان هغه د سخت سېلاب په شان تعقیبوي خپل دښمنان تیاره کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nahum1_verse_8.mp3', '', 1761754199, 1761754199),
(48943, 'Nahum 1:9', 'Nahum', 1, 9, 'څه دسیسه جوړوئ تاسو د څښتن په وړاندې؟ هغه به تاسو کړي برباد په پوره توګه مخالفت کولای نه شي بیا د هغه سره څوک', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nahum1_verse_9.mp3', '', 1761754199, 1761754199),
(48944, 'Nahum 1:10', 'Nahum', 1, 10, 'لکه تاو شویو اغزیو په شان وي به نشه هغوی خپلو شرابو باندې هغوی به وسوځي د وچو بوسو په شان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nahum1_verse_10.mp3', '', 1761754199, 1761754199),
(48945, 'Nahum 1:11', 'Nahum', 1, 11, 'ای نینوا، ستا نه به یو څوک پیدا شي چې د څښتن په وړاندې به دسیسې جوړوي او بېځایه مشورې به ورکوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nahum1_verse_11.mp3', '', 1761754199, 1761754199),
(48946, 'Nahum 1:12', 'Nahum', 1, 12, 'څښتن خپل قوم ته داسې وایي: «که څه هم آشوریان قوي او ډېر زیات دي، خو هغوی به له منځه لاړ شي او ورک به شي. که څه هم ما تاسو وکړولئ، خو بیا به داسې نه کوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nahum1_verse_12.mp3', '', 1761754199, 1761754199),
(48947, 'Nahum 1:13', 'Nahum', 1, 13, 'اوس به زه ستاسو د غاړو نه د آشوریانو جغ لرې کړم او ستاسو زولنې به ماتې کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nahum1_verse_13.mp3', '', 1761754199, 1761754199),
(48948, 'Nahum 1:14', 'Nahum', 1, 14, 'څښتن د آشوریانو په هکله داسې حکم کوي: «ای نینوا! ته به اولادونه ونه لرې چې ستا نوم ورباندې یاد شي. زه به هغه د لرګي او فلزي بتان له منځه یوسم چې د هغوی د خدایانو په عبادتځایونو کې دي. زه د آشوریانو دپاره قبرونه تیاروم، ځکه هغوی د دې لایق نه دي چې ژوندي اوسي!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nahum1_verse_14.mp3', '', 1761754199, 1761754199),
(48949, 'Nahum 1:15', 'Nahum', 1, 15, 'ګورئ، په غرونو باندې یو پیغام رسوونکی د یو زیري سره راروان دی! هغه راروان دی چې د سولې او سلامتۍ اعلان وکړي! ای د یهودا خلکو، خپل جشنونه ولمانځئ او خپلې وعده شوې نذرانې وړاندې کړئ. هغه بدکاره آشوریان به نور ستاسو په وطن باندې حمله نه کوي. هغوی به بیخي تباه شي!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nahum1_verse_15.mp3', '', 1761754199, 1761754199),
(48950, 'Psalms 134:1', 'Psalms', 134, 1, 'ای د څښتن ټول خادمانو ای هغو خلکو چې خدمت کوئ د شپې د هغه په کور کې د څښتن ثنا او صفت وکړئ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms134_verse_1.mp3', '', 1761754199, 1761754199),
(48951, 'Psalms 134:2', 'Psalms', 134, 2, 'لاسونه پورته کړئ سپېڅلي ځای ته د دعا دپاره او د څښتن ثنا او صفت وکړئ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms134_verse_2.mp3', '', 1761754199, 1761754199),
