(48953, 'Psalms 103:1', 'Psalms', 103, 1, 'ووایه ثنا د څښتن ای زما ځانه! ای زما ټول بدنه، د هغه سپېڅلی نوم ثنا ووایه!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms103_verse_1.mp3', '', 1761754199, 1761754199),
(48954, 'Psalms 103:2', 'Psalms', 103, 2, 'ووایه ثنا د څښتن ای زما ځانه! مه هېروه ټول احسانونه یې ته!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms103_verse_2.mp3', '', 1761754199, 1761754199),
(48955, 'Psalms 103:3', 'Psalms', 103, 3, 'څوک چې ستا ټول ګناهونه بخښي او ستا ټول رنځونه روغوي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms103_verse_3.mp3', '', 1761754199, 1761754199),
(48956, 'Psalms 103:4', 'Psalms', 103, 4, 'څوک چې ژغوري تا له مرګه او خپل د مینې او رحم تاج ستا په سر باندې ږدي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms103_verse_4.mp3', '', 1761754199, 1761754199),
(48957, 'Psalms 103:5', 'Psalms', 103, 5, 'چې پوره کوي څوک ارمانونه ستا په ښو شیانو ترڅو تازه شي د عقاب په څېر ستا ځواک او ځواني', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms103_verse_5.mp3', '', 1761754199, 1761754199),
(48958, 'Psalms 103:6', 'Psalms', 103, 6, 'څښتن کوي انصاف د ټولو مظلومانو سره ورکوي بېرته د هغوی حقونه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms103_verse_6.mp3', '', 1761754199, 1761754199),
(48959, 'Psalms 103:7', 'Psalms', 103, 7, 'موسی ته یې خپله اراده وښوده د اسراییلو قوم ته یې خپلې کارنامې وښودې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms103_verse_7.mp3', '', 1761754199, 1761754199),
