(48961, 'Psalms 103:9', 'Psalms', 103, 9, 'نه به ورکوي دوام رټلو ته نه به خپل قهر ساتي زړه کې تل مدام', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms103_verse_9.mp3', '', 1761754199, 1761754199),
(48962, 'Psalms 103:10', 'Psalms', 103, 10, 'نه راکوي مونږ ته زمونږ د ګناهونو سره سمه سزا نه اخلي بدله زمونږ د بدو کارو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms103_verse_10.mp3', '', 1761754199, 1761754199),
(48963, 'Psalms 103:11', 'Psalms', 103, 11, 'لکه چې څومره دی د ځمکې نه اسمان اوچت دومره یې مینه ده تلپاتې د هغو دپاره چې وېریږي ترې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms103_verse_11.mp3', '', 1761754199, 1761754199),
