(48965, 'Psalms 103:13', 'Psalms', 103, 13, 'څومره چې پلار وي مهربان خپلو بچیو باندې دومره څښتن وي مهربان په هغو خلکو باندې چې کوي وېره ترې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms103_verse_13.mp3', '', 1761754199, 1761754199),
(48966, 'Psalms 103:14', 'Psalms', 103, 14, 'هغه پوهیږي چې مونږ څنګه پیدا شوي یو هغه ته یاد دي چې له خاورې پیدا شوي یو مونږ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms103_verse_14.mp3', '', 1761754199, 1761754199),
(48967, 'Psalms 103:15', 'Psalms', 103, 15, 'د انسان ژوند دی د واښو په شان چې د صحرا د ګل په شان غوړیږي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms103_verse_15.mp3', '', 1761754199, 1761754199),
(48968, 'Psalms 103:16', 'Psalms', 103, 16, 'کله چې باد ولګي نو ځي له منځه او بیا نه ښکاري په خپل ځای کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms103_verse_16.mp3', '', 1761754199, 1761754199),
(48969, 'Psalms 103:17', 'Psalms', 103, 17, 'خو د څښتن مینه د ازل نه تر ابده به وي د هغو خلکو سره چې کوي وېره ترې د ده نېکي به وي مدام د هغوی د نسلونو سره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms103_verse_17.mp3', '', 1761754199, 1761754199),
(48970, 'Psalms 103:18', 'Psalms', 103, 18, 'د هغو خلکو سره چې وفادار اوسي د هغه لوظ ته او په حکمونو یې عمل کوي په غور سره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms103_verse_18.mp3', '', 1761754199, 1761754199),
(48971, 'Psalms 103:19', 'Psalms', 103, 19, 'څښتن خپل تخت ځای په ځای کړی په اسمان کې او پاچاهي کوي په ټولو باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms103_verse_19.mp3', '', 1761754199, 1761754199),
(48972, 'Psalms 103:20', 'Psalms', 103, 20, 'ای زورورو فرښتو چې کړئ عمل یې په حکمونو او خبره یې اورئ ثنا ووایئ د څښتن', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms103_verse_20.mp3', '', 1761754199, 1761754199),
(48973, 'Psalms 103:21', 'Psalms', 103, 21, 'ثنا ووایئ د څښتن ای د هغه د فرښتو ډلو ای خادمانو د هغه چې اراده یې پوره کوئ تاسو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms103_verse_21.mp3', '', 1761754199, 1761754199),
(48974, 'Psalms 103:22', 'Psalms', 103, 22, 'ای د څښتن ټول مخلوقه، د هغه ثنا ووایئ ده په هر هغه ځای کې پاچاهي د هغه ووایه ثنا د څښتن ای زما ځانه!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms103_verse_22.mp3', '', 1761754199, 1761754199),
(48975, 'Proverbs 7:1', 'Proverbs', 7, 1, 'ای زما زویه! زما خبرې په یاد ساته او حکمونه مې د خزانې په څېر په خپل زړه کې وساته.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs7_verse_1.mp3', '', 1761754199, 1761754199),
(48976, 'Proverbs 7:2', 'Proverbs', 7, 2, 'زما په حکمونو عمل کوه چې نېکمرغه ژوند ولرې او زما تعلیم د خپلو سترګو د کسي په شان وساته.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs7_verse_2.mp3', '', 1761754199, 1761754199),
(48977, 'Proverbs 7:3', 'Proverbs', 7, 3, 'هغه په خپلو ګوتو پورې وتړه او د خپل زړه په تخته یې ولیکه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs7_verse_3.mp3', '', 1761754199, 1761754199),
(48978, 'Proverbs 7:4', 'Proverbs', 7, 4, 'حکمت ته خپله خور ووایه عقل او پوهه ډېر نژدې خپلوان وګڼه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs7_verse_4.mp3', '', 1761754199, 1761754199),
(48979, 'Proverbs 7:5', 'Proverbs', 7, 5, 'نو دوی به تا د بل چا د ښځې نه لېرې وساتي د هغې ښځې نه چې غوړې خبرې کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs7_verse_5.mp3', '', 1761754199, 1761754199),
(48980, 'Proverbs 7:6', 'Proverbs', 7, 6, 'زه یو وخت د خپل کور په کړکۍ کې ولاړ وم او د کړکۍ له جالۍ نه مې لاندې کتل', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs7_verse_6.mp3', '', 1761754199, 1761754199),
(48981, 'Proverbs 7:7', 'Proverbs', 7, 7, 'نو ساده ځوانان مې ولیدل او د هغوی په منځ کې مې یو ناپوهه ځوان په نظر راغی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs7_verse_7.mp3', '', 1761754199, 1761754199),
(48982, 'Proverbs 7:8', 'Proverbs', 7, 8, 'هغه د هغې ښځې د کور په نژدې کوڅه کې روان ؤ او د هغې د کور په لور یې په ډاډه ډول قدمونه اخیستل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs7_verse_8.mp3', '', 1761754199, 1761754199),
(48983, 'Proverbs 7:9', 'Proverbs', 7, 9, 'د ماښام په وخت کې چې لمر پرېوته توره تیاره راغله او نیمه شپه شوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs7_verse_9.mp3', '', 1761754199, 1761754199),
(48984, 'Proverbs 7:10', 'Proverbs', 7, 10, 'ناڅاپه یوه ښځه له هغه سره مخامخ شوه چې د بدلمنۍ کالي یې اغوستي وو او نیت یې ښه نه ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs7_verse_10.mp3', '', 1761754199, 1761754199),
(48985, 'Proverbs 7:11', 'Proverbs', 7, 11, 'دا ښځه ډېره بې‌حیا او بې‌شرمه وه او له کور نه دباندې تل سرګردانه ګرځېدله', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs7_verse_11.mp3', '', 1761754199, 1761754199),
(48986, 'Proverbs 7:12', 'Proverbs', 7, 12, 'او هر وخت به کوڅو او چوکونو ته تلله او د ښار په هر ګوټ کې به په کمین کې ولاړه وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs7_verse_12.mp3', '', 1761754199, 1761754199),
(48987, 'Proverbs 7:13', 'Proverbs', 7, 13, 'نو هغې له هغه نه په زور غاړه چاپېر کړه او ښکل یې کړ او په سپین‌سترګۍ یې هغه ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs7_verse_13.mp3', '', 1761754199, 1761754199),
(48988, 'Proverbs 7:14', 'Proverbs', 7, 14, '«نن ما د قربانۍ غوښه پخه کړې ده او خپل نذر مې پوره کړی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs7_verse_14.mp3', '', 1761754199, 1761754199),
(48989, 'Proverbs 7:15', 'Proverbs', 7, 15, 'په دې خاطر زه راووتلم چې ستا سره وګورم او غوښتل مې چې تا ولټوم او پیدا مې کړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs7_verse_15.mp3', '', 1761754199, 1761754199),
(48990, 'Proverbs 7:16', 'Proverbs', 7, 16, 'ما د مصر قیمتي ټوکرونه او رنګارنګ څادرونه او ښکلي پوښونه په خپل کټ باندې غوړولي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs7_verse_16.mp3', '', 1761754199, 1761754199),
(48991, 'Proverbs 7:17', 'Proverbs', 7, 17, 'ما په خپله بستره عطر کنډ، عود او دالچیني شیندلي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs7_verse_17.mp3', '', 1761754199, 1761754199),
(48992, 'Proverbs 7:18', 'Proverbs', 7, 18, 'زما سره لاړ شه چې تر سهاره په عشق ماړه شو او د یو بل له مینې نه خوند واخلو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs7_verse_18.mp3', '', 1761754199, 1761754199),
(48993, 'Proverbs 7:19', 'Proverbs', 7, 19, 'ځکه مېړه مې په کور کې نشته هغه په یو لېرې سفر تللی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs7_verse_19.mp3', '', 1761754199, 1761754199),
(48994, 'Proverbs 7:20', 'Proverbs', 7, 20, 'د پیسو ډکه کڅوړه یې له ځان سره وړې ده او د پنځلسمې سپوږمۍ تر راختلو پورې بېرته نه راځي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs7_verse_20.mp3', '', 1761754199, 1761754199),
(48995, 'Proverbs 7:21', 'Proverbs', 7, 21, 'نو ښځې په خپلو ډېرو خوږو خبرو هغه مجبور کړ او په خپلو نرمو خبرو یې هغه بې‌لارې کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs7_verse_21.mp3', '', 1761754199, 1761754199),
(48996, 'Proverbs 7:22', 'Proverbs', 7, 22, 'نو هغه سمدلاسه په هغې پسې روان شو لکه غویی چې حلالېدو ته روان شي او د غرڅه په شان چې په ټوپونو دام ته روان وي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs7_verse_22.mp3', '', 1761754199, 1761754199),
(48997, 'Proverbs 7:23', 'Proverbs', 7, 23, 'ترڅو چې غشی یې اینه سوری کړي لکه مرغۍ چې د دام خواته په منډه روانه وي او نه پوهیږي چې خپل ژوند به له لاسه ورکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs7_verse_23.mp3', '', 1761754199, 1761754199),
(48998, 'Proverbs 7:24', 'Proverbs', 7, 24, 'نو ای زما زامنو! ماته غوږ ونیسئ او زما خبرو ته پوره پام وکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs7_verse_24.mp3', '', 1761754199, 1761754199),
(48999, 'Proverbs 7:25', 'Proverbs', 7, 25, 'خپل زړه مه پرېږدئ چې د داسې ښځې طرف ته وګرځي او یا د هغې په غلطو لارو روان شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs7_verse_25.mp3', '', 1761754199, 1761754199),
(49000, 'Proverbs 7:26', 'Proverbs', 7, 26, 'ځکه چې ډېر خلک یې ژوبل کړي دي او بې‌شمېره خلک یې وژلي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs7_verse_26.mp3', '', 1761754199, 1761754199),
(49001, 'Proverbs 7:27', 'Proverbs', 7, 27, 'د هغې د کور لارې د ګور په لور تللې دي چې د مرګ ژورې کندې ته لاندې کوزیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs7_verse_27.mp3', '', 1761754199, 1761754199),
(49002, 'Zechariah 8:1', 'Zechariah', 8, 1, 'بيا د مالِک خُدائ ربُ الافواج کلام په ما نازل شو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah8_verse_1.mp3', '', 1761754199, 1761754199),
(49003, 'Zechariah 8:2', 'Zechariah', 8, 2, 'مالِک خُدائ ربُ الافواج دا فرمائى چې، ”زۀ په يروشلم ډېر زيات غېرت کوم، زۀ د هغې دپاره سوزېږم.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah8_verse_2.mp3', '', 1761754199, 1761754199),
(49004, 'Zechariah 8:3', 'Zechariah', 8, 3, 'مالِک خُدائ دا فرمائى چې، ”زۀ به صيون ته راواپس شم او په يروشلم کښې به اوسېږم. بيا به يروشلم وفادار ښار بللے شى، او د مالِک خُدائ ربُ الافواج غر به مقدس غر بللے شى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah8_verse_3.mp3', '', 1761754199, 1761754199),
(49005, 'Zechariah 8:4', 'Zechariah', 8, 4, 'مالِک خُدائ ربُ الافواج دا فرمائى، ”يو ځل بيا به زاړۀ سړى او ښځې د يروشلم په کوڅو کښې کښېنى، هر يو سره به د بوډاتوب په وجه په لاس کښې کونټۍ وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah8_verse_4.mp3', '', 1761754199, 1761754199),
(49006, 'Zechariah 8:5', 'Zechariah', 8, 5, 'د ښار کوڅې به د هلکانو او جينکو نه ډکې وى او په کښې به لوبې کوى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah8_verse_5.mp3', '', 1761754199, 1761754199),
(49007, 'Zechariah 8:6', 'Zechariah', 8, 6, 'مالِک خُدائ ربُ الافواج دا فرمائى، ”کېدے شى چې د هغه وخت پاتې شوى خلقو ته دا ناممکنه ښکارى، خو آيا دا به ما ته هم ناممکنه ښکارى؟“ مالِک خُدائ ربُ الافواج فرمائى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah8_verse_6.mp3', '', 1761754199, 1761754199),
(49008, 'Zechariah 8:7', 'Zechariah', 8, 7, 'مالِک خُدائ ربُ الافواج دا فرمائى، ”زۀ به خپل خلق د مشرق او مغرب د مُلکونو نه بچ کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah8_verse_7.mp3', '', 1761754199, 1761754199),
(49009, 'Zechariah 8:8', 'Zechariah', 8, 8, 'زۀ به هغوئ واپس راولم چې په يروشلم کښې اوسيږى، هغوئ به زما خلق وى، او زۀ به په ايماندارۍ او صداقت د هغوئ خُدائ پاک يم.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah8_verse_8.mp3', '', 1761754199, 1761754199),
(49010, 'Zechariah 8:9', 'Zechariah', 8, 9, 'مالِک خُدائ ربُ الافواج دا فرمائى چې، ”تاسو څوک چې دا کلام اوس اورئ چې نبيانو فرمائيلے دے څوک چې هلته وُو کله چې د مالِک خُدائ ربُ الافواج د کور بنياد کېښودے شو، خپل لاسونه مضبوط کړئ چې د خُدائ پاک کور جوړ شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah8_verse_9.mp3', '', 1761754199, 1761754199);